class Biseccion:
    def __init__(self, f, tol=1e-8, max_iter=100):
        self.f = f
        self.tol = tol
        self.max_iter = max_iter
        self.historial = []

    def resolver(self, a, b):
        if self.f(a) * self.f(b) >= 0:
            raise ValueError("Bolzano no se cumple")
        for k in range(self.max_iter):
            c = (a + b) / 2
            self.historial.append((k, a, b, c, abs(self.f(c))))
            if abs(self.f(c)) < self.tol:
                return c, k
            if self.f(a) * self.f(c) < 0:
                b = c
            else:
                a = c
        raise RuntimeError("No convergió")

f = lambda x: x**3 - x - 2
bis = Biseccion(f)
raiz, iters = bis.resolver(1, 2)
print(f"Raíz: {raiz:.10f}, iteraciones: {iters}")
print(f"Iteraciones registradas: {len(bis.historial)}")

