        self.nombre = nombre

    def descripcion(self):
        return f"Un animal llamado {self.nombre}"

class Perro(Animal):
    def __init__(self, nombre, raza):
        super().__init__(nombre)   # llama al __init__ del padre
        self.raza = raza

    def descripcion(self):
        base = super().descripcion()
        return f"{base}, de raza {self.raza}"

p = Perro("Rex", "Labrador")
print(p.descripcion())   # Un animal llamado Rex, de raza Labrador

class Metodo:
    def __init__(self, f, tol=1e-8, max_iter=100):
        self.f = f
        self.tol = tol
        self.max_iter = max_iter
        self.historial = []

    def resolver(self):
        raise NotImplementedError("Subclase debe implementar resolver")

class Biseccion(Metodo):
    def resolver(self, a, b):
        if self.f(a) * self.f(b) >= 0:
            raise ValueError("Bolzano no se cumple")
        for k in range(self.max_iter):
            c = (a + b) / 2
            self.historial.append(c)
            if abs(self.f(c)) < self.tol:
                return c, k
            if self.f(a) * self.f(c) < 0:
                b = c
            else:
                a = c

class Newton(Metodo):
    def resolver(self, x0, df):
        x = x0
        for k in range(self.max_iter):
            x_nuevo = x - self.f(x) / df(x)
            self.historial.append(x_nuevo)
            if abs(x_nuevo - x) < self.tol:
                return x_nuevo, k
            x = x_nuevo

f = lambda x: x**3 - x - 2
df = lambda x: 3*x**2 - 1

bis = Biseccion(f)
raiz_b, it_b = bis.resolver(1, 2)
print(f"Bisección: {raiz_b:.10f}, iteraciones: {it_b}")

new = Newton(f)
raiz_n, it_n = new.resolver(1.5, df)
print(f"Newton:    {raiz_n:.10f}, iteraciones: {it_n}")

