class Circulo:
    def __init__(self, radio):
        self._radio = radio

    @property
    def radio(self):
        return self._radio

    @radio.setter
    def radio(self, valor):
        if valor <= 0:
            raise ValueError("El radio debe ser positivo")
        self._radio = valor

    @property
    def area(self):
        # Propiedad calculada, sin setter
        return 3.14159 * self._radio ** 2

c = Circulo(5)
print(c.radio)   # 5
print(c.area)    # 78.53975

c.radio = 10
print(c.area)    # 314.159

# c.radio = -1   # ValueError

class Resultado:
    def __init__(self, raiz, iteraciones):
        self.raiz = raiz
        self.iteraciones = iteraciones

    @property
    def convergencia(self):
        if self.iteraciones < 5:
            return "rápida"
        elif self.iteraciones < 15:
            return "normal"
        else:
            return "lenta"

r1 = Resultado(1.5213797, 3)
r2 = Resultado(1.5213797, 20)

print(r1.convergencia)   # rápida
print(r2.convergencia)   # lenta
